using System;
using SilentOrders.Core;

namespace SilentOrders.Rendering
{
    public static class UnderbarrelSprites
    {
        public static readonly SilentOrders.Rendering.PawnSprites.Sprite[] Atlas = new SilentOrders.Rendering.PawnSprites.Sprite[2]
        {
            new SilentOrders.Rendering.PawnSprites.Sprite(96, 43, ""),
            new SilentOrders.Rendering.PawnSprites.Sprite(96, 46, "")
        };
        public static readonly float[] BarrelY = new float[2]
        {
            -0.1453202f,
            -0.1161616f
        };
        public static int Height(int variant, int width)
        {
            SilentOrders.Rendering.PawnSprites.Sprite sprite = Atlas[(variant == 3) ? 1 : 0];
            return (int)System.Math.Round((float)(System.Math.Abs(width) * sprite.H) / (float)sprite.W);
        }

        public static void Draw(SilentOrders.Rendering.PixelCanvas canvas, int variant, float cx, float cy, int width, int height, float angle = 0f)
        {
            Rubezh.Graphics.Underbarrel(canvas, variant, cx, cy, width, height, angle);
        }
    }
}
